import type { CharacterTemplate } from '../types/tracing'

// The numbers 0 to 100. Each number has two parts:
//  - outline: the real shape of the number, cut from the same rounded font the app uses.
//    This is what the child sees and colours in.
//  - strokes: the centre-line in writing order. The tracing check measures against these.
// Same 300x300 grid as the letters. Every two-digit number uses the same digit size;
// 100 has three digits, so its digits are a little smaller.
// Every long string is split over several short lines on purpose, so the file survives
// being copied around on a phone.

